INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(100,'True freedom is found not in acquiring much, but in knowing what to desire.','Seneca','https://www.shaanpuri.com/mailbag/3-step-plan?_bhlid=b6302e21771140a07821ee33d4140f99ec0474ac',1,'2026-07-11 02:00:53','2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(101,'Success leaves clues','Tony Robins','https://www.shaanpuri.com/mailbag/3-step-plan?_bhlid=b6302e21771140a07821ee33d4140f99ec0474ac',1,'2026-07-28 02:00:40','2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(102,'Dreams are fun when they are distant. The imagination loves to play with possibilities when there is no risk of failure. But when you find yourself on the verge of action, you pause. You can feel the uncertainty of what lies ahead. Thoughts swirl. Maybe this isn''t the right time? Failure is possible now. In that moment—in that short pause that arises when you stand face to face with your dream—is the entirety of life. What you do in that pause is the crucible that forges you. It is the dividing line between being the type of person who thinks about it or the type of person who goes for it. When I really think about it, I want that moment to be my legacy. Not that I won or lost. Not that I looked good or looked like a fool. But that when I had something I really wanted to do, I went for it.','James Clear',NULL,0,NULL,'2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(103,'The big money isn''t in the buying and selling, it''s in the waiting','Charlie Munger',NULL,0,NULL,'2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(104,'Impatience with actions, patience with results.','Naval','https://x.com/NavalismHQ/status/1831794683271418016',1,'2026-07-12 02:00:42','2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(105,'You can carve out a very good career simply by being the most reliable person on the team. You would not think that always showing up on time, hitting every deadline, and responding quickly and professionally to all communication would be such a differentiator, but these traits are always in short supply','James Clear',NULL,0,NULL,'2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(106,'If I am worth anything later, I am worth something now. For wheat is wheat, even if people think it is a grass in the beginning','Vincent Van Gogh',NULL,0,NULL,'2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(107,'Waiting to give negative feedback to a team member is like eating an overcooked steak and waiting until the bill to dispute it.',NULL,'https://x.com/pinpulleddrmf/status/1835796724197007758?_bhlid=a3b98ebf95611f53c3fb45b89a24fb9b6e80b5e7',0,NULL,'2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(108,'If you write a problem down clearly, and specifically, you have already solved half of it','Kindlin''s Law',NULL,1,'2026-08-22 02:00:17','2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(109,'The best relationships are the ones that take the least effort. You make the other person happy by being yourself. They make you happy by being themselves. Everyone is honest and no one is putting on an act they can''t carry on for the next decade','Naval',NULL,1,'2026-08-13 02:00:22','2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(110,'You can have it all, just not all at once','Unknown',NULL,0,NULL,'2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(111,'Negotiation is the art of letting the other side have your way.','Chris Voss','https://mail.google.com/mail/u/0/#label/4.+Archive%2F3.+Resources%2FNewsletter/FMfcgzQXJQTdcbqjBxkHxkmCwktnhVbX',0,NULL,'2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(112,'I saw my life branching out before me like the green fig tree in the story. From the tip of every branch, like a fat purple fig, a wonderful future beckoned and winked. One fig was a husband and a happy home and children, and another fig was a famous poet and another fig was a brilliant professor, and another fig was Ee Gee, the amazing editor, and another fig was Europe and Africa and South America, and another fig was Constantin and Socrates and Attila and a pack of other lovers with queer names and offbeat professions, and another fig was an Olympic lady crew champion, and beyond and above these figs were many more figs I couldn''t quite make out. I saw myself sitting in the crotch of this fig tree, starving to death, just because I couldn''t make up my mind which of the figs I would choose. I wanted each and every one of them, but choosing one meant losing all the rest, and, as I sat there, unable to decide, the figs began to wrinkle and go black, and, one by one, they plopped to the ground at my feet.','Sylvia Plath','https://mail.google.com/mail/u/0/#inbox/FMfcgzQVxtmdVvlFhGdSbNxTBZZNLPlf',0,NULL,'2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(113,'If you want to be liked, get a dog!','Unknown',NULL,1,'2026-08-05 02:00:33','2026-02-05 16:53:51',NULL);
