INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(129,'Who can find a virtuous wife? For her worth is far above rubies. The heart of her husband safely trusts her; So he will have no lack of gain. She does him good and not evil All the days of her life.','Bible Proverb',NULL,0,NULL,'2026-02-05 16:53:51',NULL);
