INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(136,'Action absorbs anxiety','Scott Galloway',NULL,0,NULL,'2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(137,'The best measure of wealth is what you have minus what you want, and by this measure some billionaires are broke.','Morgan Housel','https://x.com/ChrisWillx/status/1919014144784871894?_bhlid=c8ed03e7c77835d2af656766a7f8eb90c801da3d',0,NULL,'2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(138,'The secret to winning is learning how to lose. That is, learning to bounce back from failure and disappointment—undeterred—and continuing to steadily march toward your potential. Your response to failure determines your capacity for success.','James Clear',NULL,0,NULL,'2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(139,'I slept, and dreamed that life was joy; I woke up, and found life was service; I acted and behold, service was joy','Ellen Hooper',NULL,0,NULL,'2026-02-05 16:53:51',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(140,'When the student is ready, the teacher appears. The teaching is simple, the readiness is anything but','Shreyas Doshi','https://shreyasdoshi.substack.com/p/the-humility-trap?utm_source=post-email-title&publication_id=25400&post_id=186874244&utm_campaign=email-post-title&isFreemail=true&token=eyJ1c2VyX2lkIjoxMDQ0NTc4NywicG9zdF9pZCI6MTg2ODc0MjQ0LCJpYXQiOjE3NzAyMjQ3MjUsImV4cCI6MTc3MjgxNjcyNSwiaXNzIjoicHViLTI1NDAwIiwic3ViIjoicG9zdC1yZWFjdGlvbiJ9.AHj4fGw-D8CqZ9v1OmAiXnNoGb2pZXK1upG0s69E2kk&r=67w0r&triedRedirect=true&utm_medium=email',0,NULL,'2026-02-05 16:58:44','Relates to having humility and a good litmus test is whether you are open to learning from anyone "above" or "below" you (learning is permissionless!) and actually thank them for what you learned');
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(141,'Hedge your life like a portfolio: if your time takes the risk, your money shouldn’t. If your money takes the risk, your time shouldn’t. Going all-in on both is reckless. Going all-in on neither is waste.','Danny Hakim',NULL,1,'2026-07-29 02:00:40','2026-02-06 07:49:57','The only way to make wealth is to take risk. Risk your time (entrepreneurship) or risk your money (investments) doing both is reckless and doing neither will keep you from getting financial independence');
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(142,'Nothing’s worse than getting what you want but not what you need.','Morgan Housel','Art of spending money',0,NULL,'2026-02-08 11:05:22','Sums up so many people’s relationship with money and success.');
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(143,'Many a man thinks he is buying pleasure, when he is really selling himself a slave to it.','Benjamin Franklin',NULL,0,NULL,'2026-02-08 11:44:20','Quote mentioned in Art of spending money. Discusses how if you aren’t careful money can be a big source of anxiety if you constantly chase it');
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(144,'All behaviour makes sense with enough information',NULL,'Art of spending money',0,NULL,'2026-02-08 11:58:33','Have empathy, context, and understanding before judging other people’s actions. Including how people spend money and live their life');
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(145,'emotional intelligence is the discipline of sitting with a feeling long enough to understand it before you hand it to someone else','Unknown','https://x.com/Freyy_is/status/2021311076504093073?s=20',0,NULL,'2026-02-12 03:14:32',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(146,'Comparison is the thief of joy, but inspiration is the wind that fills our sails.','Combo quote',NULL,0,NULL,'2026-03-02 05:00:58',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(147,replace('The old Master points to a big boulder and asks a disciple, “See that large rock over there?”\n“Yes,” says the disciple.\n“Do you think it’s heavy?” continues the Master.\n“Yes, it’s very heavy!” replies the student.\n“Only if you pick it up,” smiles the Master.','\n',char(10)),'Buddhist Parable','https://tim.blog/2026/03/04/the-self-help-trap/',0,NULL,'2026-03-07 04:08:25',replace('Just because something can be fixed, doesn’t mean fixing it will solve your suffering.\n\nLearn when you need to pick up the boulder, and when to stop picking them up.','\n',char(10)));
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(148,replace('God, give me grace to accept with serenity\nthe things that cannot be changed,\nCourage to change the things\nwhich should be changed,\nand the Wisdom to distinguish\nthe one from the other.','\n',char(10)),'Serenity Prayer',NULL,1,'2026-08-19 02:00:36','2026-03-07 15:14:34',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(149,'Do not disturb yourself by imagining your whole life at once.','Marcus Aurelius','https://x.com/readswithravi/status/2030289365251866763?s=20',1,'2026-07-20 02:00:39','2026-03-08 13:12:06',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(150,'We suffer more often in imagination than in reality','Seneca','https://x.com/awilkinson/status/2034639470797242598?s=20',0,NULL,'2026-03-19 16:07:38',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(151,'You worry too much for someone who figures it out every time','Unknown','https://x.com/edgaralandough/status/2036080131152715972?s=20',0,NULL,'2026-03-24 06:58:27',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(152,replace('No complaining about a situation unless you’re prepared to do something to make it better.\n\nIf you see a problem and you don’t come to the table with a potential solution, I don’t want to hear your whining about how bad it is.\n\nIt couldn’t be that bad if it hasn’t motivated you to try to fix it.​​​​​​​​​​​​​​​​','\n',char(10)),'Arnold Schwarzenegger','https://x.com/readswithravi/status/2039532195669328372?s=20',0,NULL,'2026-04-02 17:58:59',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(153,'Not needing wealth is more valuable than wealth itself.','Stoic saying',NULL,0,NULL,'2026-04-11 03:41:47',NULL);
INSERT INTO "quotes" ("id","text","author","source","sent","sent_at","created_at","note") VALUES(154,'Everyday gets a little easier, but you gotta do it everyday, that’s the hard part.',NULL,NULL,0,NULL,'2026-07-29 10:40:11','You gotta be an everyday guy. Lots of guys are someday guys. But you gotta be an everyday guy.');
